let moved = 0;
for (const c of f10.children) {
  if (c.type === "RECTANGLE" && Math.abs(c.width - 2) < 0.01 && Math.abs(c.x - 64) < 0.01) { c.x = 88; moved++; }
}
log.movedLines = moved;

return JSON.stringify(log);

